protected override def doExecute(): RDD[InternalRow] = {
  child.execute().mapPartitions(processPartition)
}

private def processPartition(rowIterator: Iterator[InternalRow]): Iterator[InternalRow] = {
  val isSourceRowPresentPred = createPredicate(isSourceRowPresent)
  val isTargetRowPresentPred = createPredicate(isTargetRowPresent)

  val matchedInstructionExecs = planInstructions(matchedInstructions)
  val notMatchedInstructionExecs = planInstructions(notMatchedInstructions)
  val notMatchedBySourceInstructionExecs = planInstructions(notMatchedBySourceInstructions)

  val cardinalityValidator = if (checkCardinality) {
    val rowIdOrdinal = child.output.indexWhere(attr => conf.resolver(attr.name, ROW_ID))
    assert(rowIdOrdinal != -1, "Cannot find row ID attr")
    BitmapCardinalityValidator(rowIdOrdinal)
  } else {
    NoopCardinalityValidator
  }

  val mergeIterator = new MergeRowIterator(
    rowIterator, cardinalityValidator, isTargetRowPresentPred, isSourceRowPresentPred,
    matchedInstructionExecs, notMatchedInstructionExecs, notMatchedBySourceInstructionExecs)

  // null indicates a record must be discarded
  mergeIterator.filter(_ != null)

// Apply an outer join to find both, matches and non-matches. We are adding two boolean fields
// with value `true`, one to each side of the join. Whether this field is null or not after
// the outer join, will allow us to identify whether the joined row was a
// matched inner result or an unmatched result with null on one side.
val joinedBaseDF = {
  var sourceDF = getMergeSource.df
  if (deduplicateCDFDeletes.enabled && deduplicateCDFDeletes.includesInserts) {
    // Add row index for the source rows to identify inserted rows during the cdf deleted rows
    // deduplication. See [[deduplicateCDFDeletes()]]
    sourceDF = sourceDF.withColumn(SOURCE_ROW_INDEX_COL, monotonically_increasing_id())
  }
  val left = sourceDF
      .withColumn(SOURCE_ROW_PRESENT_COL, Column(incrSourceRowCountExpr))
      // In some cases, the optimizer (incorrectly) decides to omit the metrics column.
      // This causes issues in the source determinism validation. We work around the issue by
      // adding a redundant dummy filter to make sure the column is not pruned.
      .filter(SOURCE_ROW_PRESENT_COL)

  val targetDF = baseTargetDF
    .withColumn(TARGET_ROW_PRESENT_COL, lit(true))
  val right = if (deduplicateCDFDeletes.enabled) {
    targetDF.withColumn(TARGET_ROW_INDEX_COL, monotonically_increasing_id())
  } else {
    targetDF
  }
  left.join(right, Column(condition), joinType)
}

// Precompute conditions in matched and not matched clauses and generate
// the joinedDF with precomputed columns and clauses with rewritten conditions.
val (joinedAndPrecomputedConditionsDF, clausesWithPrecompConditions) =
    generatePrecomputedConditionsAndDF(
      joinedDF,
      clauses = matchedClauses ++ notMatchedClauses ++ notMatchedBySourceClauses)

// In case Row IDs are preserved, get the attribute expression of the Row ID column.
val rowIdColumnExpressionOpt =
  MaterializedRowId.getAttribute(deltaTxn.snapshot, joinedAndPrecomputedConditionsDF)

val rowCommitVersionColumnExpressionOpt =
  MaterializedRowCommitVersion.getAttribute(deltaTxn.snapshot, joinedAndPrecomputedConditionsDF)

// The target output columns need to be marked as nullable here, as they are going to be used
// to reference the output of an outer join.
val targetWriteCols = postEvolutionTargetExpressions(makeNullable = true)

// If there are N columns in the target table, the full outer join output will have:
// - N columns for target table
// - Two optional Row ID / Row commit version preservation columns with their physical name.
// - ROW_DROPPED_COL to define whether the generated row should be dropped or written
// - if CDC is enabled, also CDC_TYPE_COLUMN_NAME with the type of change being performed
//   in a particular row
// (N+1 or N+2 columns depending on CDC disabled / enabled)
val outputColNames =
  targetWriteCols.map(_.name) ++
    rowIdColumnExpressionOpt.map(_.name) ++
    rowCommitVersionColumnExpressionOpt.map(_.name) ++
    Seq(ROW_DROPPED_COL) ++
    (if (cdcEnabled) Some(CDC_TYPE_COLUMN_NAME) else None)

// Copy expressions to copy the existing target row and not drop it (ROW_DROPPED_COL=false),
// and in case CDC is enabled, set it to CDC_TYPE_NOT_CDC.
// (N+1 or N+2 or N+3 columns depending on CDC disabled / enabled and if Row IDs are preserved)
val noopCopyExprs =
  targetWriteCols ++
    rowIdColumnExpressionOpt ++
    rowCommitVersionColumnExpressionOpt ++
    Seq(incrNoopCountExpr) ++
    (if (cdcEnabled) Seq(CDC_TYPE_NOT_CDC) else Seq())

// Generate output columns.
val outputCols = generateWriteAllChangesOutputCols(
  targetWriteCols,
  rowIdColumnExpressionOpt,
  rowCommitVersionColumnExpressionOpt,
  outputColNames,
  noopCopyExprs,
  clausesWithPrecompConditions,
  cdcEnabled
)

val preOutputDF = if (cdcEnabled) {
  generateCdcAndOutputRows(
      joinedAndPrecomputedConditionsDF,
      outputCols,
      outputColNames,
      noopCopyExprs,
      rowIdColumnExpressionOpt.map(_.name),
      rowCommitVersionColumnExpressionOpt.map(_.name),
      deduplicateCDFDeletes)
} else {
  // change data capture is off, just output the normal data
  joinedAndPrecomputedConditionsDF
    .select(outputCols: _*)
}
// The filter ensures we only consider rows that are not dropped.
// The drop ensures that the dropped flag does not leak out to the output.
val outputDF = preOutputDF
  .filter(s"$ROW_DROPPED_COL = false")
  .drop(ROW_DROPPED_COL)

logDebug("writeAllChanges: join output plan:\n" + outputDF.queryExecution)

// Write to Delta
val newFiles = writeFiles(spark, deltaTxn, outputDF)

// Fake projection used to resolve generated column expressions.
val fakeProjectMap = allActions.map {
  action => {
    val exprForProject = Alias(action.expr, action.targetColNameParts.head)()
    exprForProject.exprId -> exprForProject
  }
}.toMap
val fakeProject = Project(fakeProjectMap.values.toArray[Alias], sourcePlan)

val resolvedActions = allActions.map { action =>
  val colName = action.targetColNameParts.head
  implicitColumns.find {
    case (field, _) => conf.resolver(field.name, colName)
  } match {
    case Some((field, true)) =>
      val expr = GeneratedColumn.getGenerationExpression(field).get
      val resolvedExpr = resolveReferencesForExpressions(SparkSession.active, expr :: Nil,
        fakeProject).head
      // Replace references to fakeProject with original expression.
      val transformedExpr = resolvedExpr.transform {
        case a: AttributeReference if fakeProjectMap.contains(a.exprId) =>
          fakeProjectMap(a.exprId).child
      }
      action.copy(expr = transformedExpr)
    case Some((field, false)) =>
      // This is the IDENTITY column case. Track the high water marks collection and produce
      // IDENTITY value generation function.
      track += field.name
      // Reuse the existing identityExp which we might have already generated. This is to make
      // sure that we use the same identity column generation expression across different
      // WHEN NOT MATCHED branches for a given identity column - so that we can generate
      // identity values from the same generator and prevent duplicate identity values.
      val identityExp = identityColumnExpressionMap.getOrElseUpdate(
        field, IdentityColumn.createIdentityColumnGenerationExpr(field))
      action.copy(expr = identityExp)
    case _ => action
  }
}
(resolvedActions, track.toSet)

def merge(source: DataFrame, condition: Column): DeltaMergeBuilder = {
  DeltaMergeBuilder(this, source, condition)
}

def execute(): DataFrame = improveUnsupportedOpError {
  val sparkSession = targetTable.toDF.sparkSession
  withActiveSession(sparkSession) {
    // Note: We are explicitly resolving DeltaMergeInto plan rather than going to through the
    // Analyzer using `Dataset.ofRows()` because the Analyzer incorrectly resolves all
    // references in the DeltaMergeInto using both source and target child plans, even before
    // DeltaAnalysis rule kicks in. This is because the Analyzer  understands only MergeIntoTable,
    // and handles that separately by skipping resolution (for Delta) and letting the
    // DeltaAnalysis rule do the resolving correctly. This can be solved by generating
    // MergeIntoTable instead, which blocked by the different issue with MergeIntoTable as
    // explained in the function `mergePlan` and
    // https://issues.apache.org/jira/browse/SPARK-34962.
    val resolvedMergeInto =
    ResolveDeltaMergeInto.resolveReferencesAndSchema(mergePlan, sparkSession.sessionState.conf)(
      tryResolveReferencesForExpressions(sparkSession))

    val strippedMergeInto = resolvedMergeInto.copy(
      target = DeltaViewHelper.stripTempViewForMerge(resolvedMergeInto.target, SQLConf.get)
    )
    // Preprocess the actions and verify
    var mergeIntoCommand =
      PreprocessTableMerge(sparkSession.sessionState.conf)(strippedMergeInto)
    // Resolve UpCast expressions that `PreprocessTableMerge` may have introduced.
    mergeIntoCommand = PostHocResolveUpCast(sparkSession).apply(mergeIntoCommand)
    sparkSession.sessionState.analyzer.checkAnalysis(mergeIntoCommand)
    toDataset(sparkSession, mergeIntoCommand)

// Note: The Scala API cannot generate MergeIntoTable just like the SQL parser because
// UpdateAction in MergeIntoTable does not have any way to differentiate between
// the representations of `updateAll()` and `update(some-condition, empty-actions)`.
// More specifically, UpdateAction with a list of empty Assignments implicitly represents
// `updateAll()`, so there is no way to represent `update()` with zero column assignments
// (possible in Scala API, but syntactically not possible in SQL). This issue is tracked
// by https://issues.apache.org/jira/browse/SPARK-34962.
val merge = DeltaMergeInto(
  targetPlan, sourcePlan, condition, clauses, withSchemaEvolution = schemaEvolutionEnabled)
logDebug("Generated merged plan:\n" + merge)
merge

case u @ UpdateTable(table, assignments, condition) if u.childrenResolved =>
  val (cols, expressions) = assignments.map(a => a.key -> a.value).unzip
  // rewrites Delta from V2 to V1
  val newTable = stripTempViewWrapper(table).transformUp { case DeltaRelation(lr) => lr }
    newTable.collectLeaves().headOption match {
      case Some(DeltaFullTable(_, index)) =>
        DeltaUpdateTable(newTable, cols, expressions, condition)
      case o =>
        // not a Delta table
        u
    }

def toCommand(update: DeltaUpdateTable): UpdateCommand = {
  val deltaLogicalNode = EliminateSubqueryAliases(update.child)
  val (relation, index) = deltaLogicalNode match {
    case DeltaFullTable(rel, tahoeFileIndex) => rel -> tahoeFileIndex
    case o =>
      throw DeltaErrors.notADeltaSourceException("UPDATE", Some(o))
  }

  val generatedColumns = GeneratedColumn.getGeneratedColumns(index)
  if (generatedColumns.nonEmpty &&
      !GeneratedColumn.allowDMLTargetPlan(deltaLogicalNode, conf)) {
    // Disallow temp views referring to a Delta table that contains generated columns. When the
    // user doesn't provide expressions for generated columns, we need to create update
    // expressions for them automatically. Currently, we assume `update.child.output` is the same
    // as the table schema when checking whether a column in `update.child.output` is a generated
    // column in the table.
    throw DeltaErrors.operationOnTempViewWithGenerateColsNotSupported("UPDATE")
  }

  val targetColNameParts = update.updateColumns.map(DeltaUpdateTable.getTargetColNameParts(_))

  IdentityColumn.blockIdentityColumnUpdate(index.snapshotAtAnalysis.schema, targetColNameParts)

  val alignedUpdateExprs = generateUpdateExpressions(
    targetSchema = update.child.schema,
    defaultExprs = update.child.output,
    nameParts = targetColNameParts,
    updateExprs = update.updateExpressions,
    resolver = conf.resolver,
    generatedColumns = generatedColumns
  )
  val alignedUpdateExprsAfterAddingGenerationExprs =
    if (alignedUpdateExprs.forall(_.nonEmpty)) {
      alignedUpdateExprs.map(_.get)
    } else {
      // Some expressions for generated columns are not specified by the user, so we need to
      // create them based on the generation expressions.
      generateUpdateExprsForGeneratedColumns(update.child, generatedColumns, alignedUpdateExprs)
    }
  UpdateCommand(
    index,
    relation.catalogTable,
    update.child,
    alignedUpdateExprsAfterAddingGenerationExprs,
    update.condition)

// Prune non-matching files if we don't need to collect them for NOT MATCHED BY SOURCE clauses.
val dataSkippedFiles =
  if (notMatchedBySourceClauses.isEmpty) {
    deltaTxn.filterFiles(getTargetOnlyPredicates(spark), keepNumRecords = true)
  } else {
    deltaTxn.filterFiles(filters = Seq(Literal.TrueLiteral), keepNumRecords = true)
  }

// Join the source and target table using the merge condition to find touched files. An inner
// join collects all candidate files for MATCHED clauses, a right outer join also includes
// candidates for NOT MATCHED BY SOURCE clauses.
// In addition, we attach two columns
// - a monotonically increasing row id for target rows to later identify whether the same
//     target row is modified by multiple user or not
// - the target file name the row is from to later identify the files touched by matched rows
val joinType = if (notMatchedBySourceClauses.isEmpty) "inner" else "right_outer"

// When they are only MATCHED clauses, after the join we prune files that have no rows that
// satisfy any of the clause conditions.
val matchedPredicate =
  if (isMatchedOnly) {
    matchedClauses
      // An undefined condition (None) is implicitly true
      .map(_.condition.getOrElse(Literal.TrueLiteral))
      .reduce((a, b) => Or(a, b))
  } else Literal.TrueLiteral

// Compute the columns needed for the inner join.
val targetColsNeeded = {
  condition.references.map(_.name) ++ deltaTxn.snapshot.metadata.partitionColumns ++
    matchedPredicate.references.map(_.name)
}

val columnsToDrop = deltaTxn.snapshot.metadata.schema.map(_.name)
  .filterNot { field =>
    targetColsNeeded.exists { name => columnComparator(name, field) }
  }
val incrSourceRowCountExpr = incrementMetricAndReturnBool("numSourceRows", valueToReturn = true)
// We can't use filter() directly on the expression because that will prevent
// column pruning. We don't need the SOURCE_ROW_PRESENT_COL so we immediately drop it.
val sourceDF = getMergeSource.df
  .withColumn(SOURCE_ROW_PRESENT_COL, Column(incrSourceRowCountExpr))
  .filter(SOURCE_ROW_PRESENT_COL)
  .drop(SOURCE_ROW_PRESENT_COL)
val targetPlan =
  buildTargetPlanWithFiles(
    spark,
    deltaTxn,
    dataSkippedFiles,
    columnsToDrop)
val targetDF = DataFrameUtils.ofRows(spark, targetPlan)
  .withColumn(ROW_ID_COL, monotonically_increasing_id())
  .withColumn(FILE_NAME_COL, input_file_name())

val joinToFindTouchedFiles =
  sourceDF.join(targetDF, Column(condition), joinType)

SQLExecution.withNewExecutionId(queryExecution, Option("deltaTransactionalWrite")) {
  val outputSpec = FileFormatWriter.OutputSpec(
    outputPath.toString,
    Map.empty,
    output)

  val empty2NullPlan = convertEmptyToNullIfNeeded(queryExecution.executedPlan,
    partitioningColumns, constraints)
  val checkInvariants = DeltaInvariantCheckerExec(spark, empty2NullPlan, constraints)
  // No need to plan optimized write if the write command is OPTIMIZE, which aims to produce
  // evenly-balanced data files already.
  val physicalPlan = if (!isOptimize &&
    shouldOptimizeWrite(writeOptions, spark.sessionState.conf)) {
    DeltaOptimizedWriterExec(checkInvariants, metadata.partitionColumns, deltaLog)
  } else {
    checkInvariants
  }

  val statsTrackers: ListBuffer[WriteJobStatsTracker] = ListBuffer()

  if (spark.conf.get(DeltaSQLConf.DELTA_HISTORY_METRICS_ENABLED)) {
    val basicWriteJobStatsTracker = new BasicWriteJobStatsTracker(
      new SerializableConfiguration(deltaLog.newDeltaHadoopConf()),
      BasicWriteJobStatsTracker.metrics)
    registerSQLMetrics(spark, basicWriteJobStatsTracker.driverSideMetrics)
    statsTrackers.append(basicWriteJobStatsTracker)
  }

  // Iceberg spec requires partition columns in data files
  val writePartitionColumns = IcebergCompat.isAnyEnabled(metadata)
  // Retain only a minimal selection of Spark writer options to avoid any potential
  // compatibility issues
  val options = (writeOptions match {
    case None => Map.empty[String, String]
    case Some(writeOptions) =>
      writeOptions.options.filterKeys { key =>
        key.equalsIgnoreCase(DeltaOptions.MAX_RECORDS_PER_FILE) ||
          key.equalsIgnoreCase(DeltaOptions.COMPRESSION)
      }.toMap
  }) + (DeltaOptions.WRITE_PARTITION_COLUMNS -> writePartitionColumns.toString)

  try {
    DeltaFileFormatWriter.write(
      sparkSession = spark,
      plan = physicalPlan,
      fileFormat = deltaLog.fileFormat(protocol, metadata), // TODO support changing formats.
      committer = committer,
      outputSpec = outputSpec,
      // scalastyle:off deltahadoopconfiguration
      hadoopConf =
        spark.sessionState.newHadoopConfWithOptions(metadata.configuration ++ deltaLog.options),
      // scalastyle:on deltahadoopconfiguration
      partitionColumns = partitioningColumns,
      bucketSpec = None,
      statsTrackers = optionalStatsTracker.toSeq
        ++ statsTrackers
        ++ identityTrackerOpt.toSeq,
      options = options)

// Iceberg spec requires partition columns in data files
val writePartitionColumns = IcebergCompat.isAnyEnabled(metadata)
// Retain only a minimal selection of Spark writer options to avoid any potential
// compatibility issues
val options = (writeOptions match {
  case None => Map.empty[String, String]
  case Some(writeOptions) =>
    writeOptions.options.filterKeys { key =>
      key.equalsIgnoreCase(DeltaOptions.MAX_RECORDS_PER_FILE) ||
        key.equalsIgnoreCase(DeltaOptions.COMPRESSION)
    }.toMap
}) + (DeltaOptions.WRITE_PARTITION_COLUMNS -> writePartitionColumns.toString)

try {
  DeltaFileFormatWriter.write(
    sparkSession = spark,
    plan = physicalPlan,
    fileFormat = deltaLog.fileFormat(protocol, metadata), // TODO support changing formats.
    committer = committer,
    outputSpec = outputSpec,
    // scalastyle:off deltahadoopconfiguration
    hadoopConf =
      spark.sessionState.newHadoopConfWithOptions(metadata.configuration ++ deltaLog.options),
    // scalastyle:on deltahadoopconfiguration
    partitionColumns = partitioningColumns,
    bucketSpec = None,
    statsTrackers = optionalStatsTracker.toSeq
      ++ statsTrackers
      ++ identityTrackerOpt.toSeq,
    options = options)

private def writeAndCommit(
    job: Job,
    description: WriteJobDescription,
    committer: FileCommitProtocol)(f: => Array[WriteTaskResult]): Set[String] = {
  // This call shouldn't be put into the `try` block below because it only initializes and
  // prepares the job, any exception thrown from here shouldn't cause abortJob() to be called.
  committer.setupJob(job)
  try {
    val ret = f
    val commitMsgs = ret.map(_.commitMsg)

    logInfo(log"Start to commit write Job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)}.")
    val (_, duration) = Utils.timeTakenMs { committer.commitJob(job, commitMsgs) }
    logInfo(log"Write Job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)} committed. " +
      log"Elapsed time: ${MDC(DeltaLogKeys.DURATION, duration)} ms.")

    processStats(description.statsTrackers, ret.map(_.summary.stats), duration)
    logInfo(log"Finished processing stats for write job " +
      log"${MDC(DeltaLogKeys.JOB_ID, description.uuid)}.")

    // return a set of all the partition paths that were updated during this job
    ret.map(_.summary.updatedPartitions).reduceOption(_ ++ _).getOrElse(Set.empty)
  } catch {
    case cause: Throwable =>
      logError(log"Aborting job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)}", cause)
      committer.abortJob(job)
      throw cause

override def setupJob(jobContext: JobContext): Unit = {

}

/**
 * Commits a job after the writes succeed. Must be called on the driver. Partitions the written
 * files into [[AddFile]]s and [[AddCDCFile]]s as these metadata actions are treated differently
 * by [[TransactionalWrite]] (i.e. AddFile's may have additional statistics injected)
 */
override def commitJob(jobContext: JobContext, taskCommits: Seq[TaskCommitMessage]): Unit = {
  val (addFiles, changeFiles) = taskCommits.flatMap(_.obj.asInstanceOf[Seq[_]])
    .partition {
      case _: AddFile => true
      case _: AddCDCFile => false
      case other =>
        throw DeltaErrors.unrecognizedFileAction(s"$other", s"${other.getClass}")
    }

  // we cannot add type information above because of type erasure
  addedStatuses ++= addFiles.map(_.asInstanceOf[AddFile])
  this.changeFiles ++= changeFiles.map(_.asInstanceOf[AddCDCFile]).toArray[AddCDCFile]
}

override def abortJob(jobContext: JobContext): Unit = {
  // TODO: Best effort cleanup
}

override def commitJob(jobContext: JobContext, taskCommits: Seq[TaskCommitMessage]): Unit = {
  committer.commitJob(jobContext)

  if (hasValidPath) {
    val (allAbsPathFiles, allPartitionPaths) =
      taskCommits.map(_.obj.asInstanceOf[(Map[String, String], Set[String])]).unzip
    val fs = stagingDir.getFileSystem(jobContext.getConfiguration)

    val filesToMove = allAbsPathFiles.foldLeft(Map[String, String]())(_ ++ _)
    logDebug(s"Committing files staged for absolute locations $filesToMove")
    val absParentPaths = filesToMove.values.map(new Path(_).getParent).toSet
    if (dynamicPartitionOverwrite) {
      logDebug(s"Clean up absolute partition directories for overwriting: $absParentPaths")
      absParentPaths.foreach(fs.delete(_, true))
    }
    logDebug(s"Create absolute parent directories: $absParentPaths")
    absParentPaths.foreach(fs.mkdirs)
    for ((src, dst) <- filesToMove) {
      if (!fs.rename(new Path(src), new Path(dst))) {
        throw new IOException(s"Failed to rename $src to $dst when committing files staged for " +
          s"absolute locations")
      }
    }

    if (dynamicPartitionOverwrite) {
      val partitionPaths = allPartitionPaths.foldLeft(Set[String]())(_ ++ _)
      logDebug(s"Clean up default partition directories for overwriting: $partitionPaths")
      for (part <- partitionPaths) {
        val finalPartPath = new Path(path, part)
        if (!fs.delete(finalPartPath, true) && !fs.exists(finalPartPath.getParent)) {
          // According to the official hadoop FileSystem API spec, delete op should assume
          // the destination is no longer present regardless of return value, thus we do not
          // need to double check if finalPartPath exists before rename.
          // Also in our case, based on the spec, delete returns false only when finalPartPath
          // does not exist. When this happens, we need to take action if parent of finalPartPath
          // also does not exist(e.g. the scenario described on SPARK-23815), because
          // FileSystem API spec on rename op says the rename dest(finalPartPath) must have
          // a parent that exists, otherwise we may get unexpected result on the rename.
          fs.mkdirs(finalPartPath.getParent)
        }
        val stagingPartPath = new Path(stagingDir, part)
        if (!fs.rename(stagingPartPath, finalPartPath)) {
          throw new IOException(s"Failed to rename $stagingPartPath to $finalPartPath when " +
            s"committing files staged for overwriting dynamic partitions")
        }
      }
    }

    fs.delete(stagingDir, true)
  }
}

override def commitJob(jobContext: JobContext, taskCommits: Seq[TaskCommitMessage]): Unit = {
  committer.commitJob(jobContext)

  if (hasValidPath) {
    val (allAbsPathFiles, allPartitionPaths) =
      taskCommits.map(_.obj.asInstanceOf[(Map[String, String], Set[String])]).unzip
    val fs = stagingDir.getFileSystem(jobContext.getConfiguration)

    val filesToMove = allAbsPathFiles.foldLeft(Map[String, String]())(_ ++ _)
    logDebug(s"Committing files staged for absolute locations $filesToMove")
    val absParentPaths = filesToMove.values.map(new Path(_).getParent).toSet
    if (dynamicPartitionOverwrite) {
      logDebug(s"Clean up absolute partition directories for overwriting: $absParentPaths")
      absParentPaths.foreach(fs.delete(_, true))
    }
    logDebug(s"Create absolute parent directories: $absParentPaths")
    absParentPaths.foreach(fs.mkdirs)
    for ((src, dst) <- filesToMove) {
      if (!fs.rename(new Path(src), new Path(dst))) {
        throw new IOException(s"Failed to rename $src to $dst when committing files staged for " +
          s"absolute locations")
      }
    }

    if (dynamicPartitionOverwrite) {
      val partitionPaths = allPartitionPaths.foldLeft(Set[String]())(_ ++ _)
      logDebug(s"Clean up default partition directories for overwriting: $partitionPaths")
      for (part <- partitionPaths) {
        val finalPartPath = new Path(path, part)
        if (!fs.delete(finalPartPath, true) && !fs.exists(finalPartPath.getParent)) {
          // According to the official hadoop FileSystem API spec, delete op should assume
          // the destination is no longer present regardless of return value, thus we do not
          // need to double check if finalPartPath exists before rename.
          // Also in our case, based on the spec, delete returns false only when finalPartPath
          // does not exist. When this happens, we need to take action if parent of finalPartPath
          // also does not exist(e.g. the scenario described on SPARK-23815), because
          // FileSystem API spec on rename op says the rename dest(finalPartPath) must have
          // a parent that exists, otherwise we may get unexpected result on the rename.
          fs.mkdirs(finalPartPath.getParent)
        }
        val stagingPartPath = new Path(stagingDir, part)
        if (!fs.rename(stagingPartPath, finalPartPath)) {
          throw new IOException(s"Failed to rename $stagingPartPath to $finalPartPath when " +
            s"committing files staged for overwriting dynamic partitions")
        }
      }
    }

    fs.delete(stagingDir, true)
  }
}

