private def executeWrite(
    sparkSession: SparkSession,
    plan: SparkPlan,
    job: Job,
    description: WriteJobDescription,
    committer: FileCommitProtocol,
    outputSpec: OutputSpec,
    requiredOrdering: Seq[Expression],
    partitionColumns: Seq[Attribute],
    sortColumns: Seq[Attribute],
    orderingMatched: Boolean): Set[String] = {
  val projectList = V1WritesUtils.convertEmptyToNull(plan.output, partitionColumns)
  val empty2NullPlan = if (projectList.nonEmpty) ProjectExec(projectList, plan) else plan

  writeAndCommit(job, description, committer) {
    val (planToExecute, concurrentOutputWriterSpec) = if (orderingMatched) {
      (empty2NullPlan, None)
    } else {
      val sortPlan = createSortPlan(empty2NullPlan, requiredOrdering, outputSpec)
      val concurrentOutputWriterSpec =
        createConcurrentOutputWriterSpec(sparkSession, sortPlan, sortColumns)
      if (concurrentOutputWriterSpec.isDefined) {
        (empty2NullPlan, concurrentOutputWriterSpec)
      } else {
        (sortPlan, concurrentOutputWriterSpec)
      }
    }

    // In testing, this is the only way to get hold of the actually executed plan written to file
    if (DeltaUtils.isTesting) executedPlan = Some(planToExecute)

    val rdd = planToExecute.execute()

    // SPARK-23271 If we are attempting to write a zero partition rdd, create a dummy single
    // partition rdd to make sure we at least set up one write task to write the metadata.
    val rddWithNonEmptyPartitions = if (rdd.partitions.length == 0) {
      sparkSession.sparkContext.parallelize(Array.empty[InternalRow], 1)
    } else {
      rdd
    }

    val jobTrackerID = SparkHadoopWriterUtils.createJobTrackerID(new Date())
    val ret = new Array[WriteTaskResult](rddWithNonEmptyPartitions.partitions.length)
    val partitionColumnToDataType = description.partitionColumns
      .map(attr => (attr.name, attr.dataType)).toMap
    sparkSession.sparkContext.runJob(
      rddWithNonEmptyPartitions,
      (taskContext: TaskContext, iter: Iterator[InternalRow]) => {
        executeTask(
          description = description,
          jobTrackerID = jobTrackerID,
          sparkStageId = taskContext.stageId(),
          sparkPartitionId = taskContext.partitionId(),
          sparkAttemptNumber = taskContext.taskAttemptId().toInt & Integer.MAX_VALUE,
          committer,
          iterator = iter,
          concurrentOutputWriterSpec = concurrentOutputWriterSpec,
          partitionColumnToDataType
        )
      },
      rddWithNonEmptyPartitions.partitions.indices,
      (index, res: WriteTaskResult) => {
        committer.onTaskCommit(res.commitMsg)

private def writeAndCommit(
    job: Job,
    description: WriteJobDescription,
    committer: FileCommitProtocol)(f: => Array[WriteTaskResult]): Set[String] = {
  // This call shouldn't be put into the `try` block below because it only initializes and
  // prepares the job, any exception thrown from here shouldn't cause abortJob() to be called.
  committer.setupJob(job)
  try {
    val ret = f
    val commitMsgs = ret.map(_.commitMsg)

    logInfo(log"Start to commit write Job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)}.")
    val (_, duration) = Utils.timeTakenMs { committer.commitJob(job, commitMsgs) }
    logInfo(log"Write Job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)} committed. " +
      log"Elapsed time: ${MDC(DeltaLogKeys.DURATION, duration)} ms.")

    processStats(description.statsTrackers, ret.map(_.summary.stats), duration)
    logInfo(log"Finished processing stats for write job " +
      log"${MDC(DeltaLogKeys.JOB_ID, description.uuid)}.")

    // return a set of all the partition paths that were updated during this job
    ret.map(_.summary.updatedPartitions).reduceOption(_ ++ _).getOrElse(Set.empty)
  } catch {
    case cause: Throwable =>
      logError(log"Aborting job ${MDC(DeltaLogKeys.JOB_ID, description.uuid)}", cause)
      committer.abortJob(job)
      throw cause

private def executeTask(
    description: WriteJobDescription,
    jobTrackerID: String,
    sparkStageId: Int,
    sparkPartitionId: Int,
    sparkAttemptNumber: Int,
    committer: FileCommitProtocol,
    iterator: Iterator[InternalRow],
    concurrentOutputWriterSpec: Option[ConcurrentOutputWriterSpec],
    partitionColumnToDataType: Map[String, DataType]): WriteTaskResult = {

  val jobId = SparkHadoopWriterUtils.createJobID(jobTrackerID, sparkStageId)
  val taskId = new TaskID(jobId, TaskType.MAP, sparkPartitionId)
  val taskAttemptId = new TaskAttemptID(taskId, sparkAttemptNumber)

  // Set up the attempt context required to use in the output committer.
  val taskAttemptContext: TaskAttemptContext = {
    // Set up the configuration object
    val hadoopConf = description.serializableHadoopConf.value
    hadoopConf.set("mapreduce.job.id", jobId.toString)
    hadoopConf.set("mapreduce.task.id", taskAttemptId.getTaskID.toString)
    hadoopConf.set("mapreduce.task.attempt.id", taskAttemptId.toString)
    hadoopConf.setBoolean("mapreduce.task.ismap", true)
    hadoopConf.setInt("mapreduce.task.partition", 0)

    if (partitionColumnToDataType.isEmpty) {
      new TaskAttemptContextImpl(hadoopConf, taskAttemptId)
    } else {
      new PartitionedTaskAttemptContextImpl(hadoopConf, taskAttemptId, partitionColumnToDataType)
    }
  }

  committer.setupTask(taskAttemptContext)

  val dataWriter =
    if (sparkPartitionId != 0 && !iterator.hasNext) {
      // In case of empty job, leave first partition to save meta for file format like parquet.
      new EmptyDirectoryDataWriter(description, taskAttemptContext, committer)
    } else if (description.partitionColumns.isEmpty && description.bucketSpec.isEmpty) {
      new SingleDirectoryDataWriter(description, taskAttemptContext, committer)
    } else {
      concurrentOutputWriterSpec match {
        case Some(spec) =>
          new DynamicPartitionDataConcurrentWriter(
            description,
            taskAttemptContext,
            committer,
            spec
          )
        case _ =>
          new DynamicPartitionDataSingleWriter(description, taskAttemptContext, committer)
      }
    }

  try {
    Utils.tryWithSafeFinallyAndFailureCallbacks(block = {
      // Execute the task to write rows out and commit the task.
      dataWriter.writeWithIterator(iterator)
      dataWriter.commit()
    })(catchBlock = {
      // If there is an error, abort the task
      dataWriter.abort()
      logError(log"Job ${MDC(DeltaLogKeys.JOB_ID, jobId)} aborted.")
    }, finallyBlock = {
      dataWriter.close()

  }

  /**
   * Returns the summary of relative information which
   * includes the list of partition strings written out. The list of partitions is sent back
   * to the driver and used to update the catalog. Other information will be sent back to the
   * driver too and used to e.g. update the metrics in UI.
   */
  final override def commit(): WriteTaskResult = enrichWriteError(description.path) {
    releaseResources()
    val (taskCommitMessage, taskCommitTime) = Utils.timeTakenMs {
      committer.commitTask(taskAttemptContext)
    }
    val summary = ExecutedWriteSummary(
      updatedPartitions = updatedPartitions.toSet,
      stats = statsTrackers.map(_.getFinalStats(taskCommitTime)))
    WriteTaskResult(taskCommitMessage, summary)
  }

  final def abort(): Unit = enrichWriteError(description.path) {
    try {
      releaseResources()
    } finally {
      committer.abortTask(taskAttemptContext)
    }
  }

  final override def close(): Unit = {}
}

