/** Extract all constraints from the given Delta table metadata. */
def getAll(metadata: Metadata, spark: SparkSession): Seq[Constraint] = {
  val checkConstraints = getCheckConstraints(metadata, spark)
  val constraintsFromSchema = Invariants.getFromSchema(metadata.schema, spark)
  val charVarcharLengthChecks = if (spark.sessionState.conf.charVarcharAsString) {
    Nil
  } else {
    CharVarcharConstraint.stringConstraints(metadata.schema)
  }

  (checkConstraints ++ constraintsFromSchema ++ charVarcharLengthChecks).toSeq
}

/** Extract invariants from the given schema */
def getFromSchema(schema: StructType, spark: SparkSession): Seq[Constraint] = {
  val columns = SchemaUtils.filterRecursively(schema, checkComplexTypes = false) { field =>
    !field.nullable || field.metadata.contains(INVARIANTS_FIELD)
  }
  columns.map {
    case (parents, field) if !field.nullable =>
      Constraints.NotNull(parents :+ field.name)
    case (parents, field) =>
      val rule = field.metadata.getString(INVARIANTS_FIELD)
      val invariant = Option(JsonUtils.mapper.readValue[PersistedRule](rule).unwrap) match {
        case Some(PersistedExpression(exprString)) =>
          ArbitraryExpression(spark, exprString)
        case _ =>
          throw DeltaErrors.unrecognizedInvariant()
      }
      Constraints.Check(invariant.name, invariant.expression)
  }
}

def buildInvariantChecks(
    output: Seq[Attribute],
    constraints: Seq[Constraint],
    spark: SparkSession): Seq[CheckDeltaInvariant] = {
  constraints.map { constraint =>
    val columnExtractors = mutable.Map[String, Expression]()
    val executableExpr = constraint match {
      case n @ NotNull(column) =>
        buildExtractor(output, column).getOrElse {
          throw DeltaErrors.notNullColumnMissingException(n)
        }
      case Check(name, expr) =>
        // We need to do two stages of resolution here:
        //  * Build the extractors to evaluate attribute references against input InternalRows.
        //  * Do logical analysis to handle nested field extractions, functions, etc.

        val attributesExtracted = expr.transformUp {
          case a: UnresolvedAttribute =>
            val ex = buildExtractor(output, a.nameParts).getOrElse(Literal(null))
            columnExtractors(a.name) = ex
            ex
        }

        val wrappedPlan: LogicalPlan = ExpressionLogicalPlanWrapper(attributesExtracted)
        val analyzedLogicalPlan = spark.sessionState.analyzer.execute(wrappedPlan)
        val optimizedLogicalPlan = DeltaInvariantCheckerOptimizer.execute(analyzedLogicalPlan)
        val resolvedExpr = optimizedLogicalPlan match {
          case ExpressionLogicalPlanWrapper(e) => e
          // This should never happen.
          case plan => throw new DeltaIllegalStateException(
            errorClass = "INTERNAL_ERROR",
            messageParameters = Array(
              "Applying type casting resulted in a bad plan rather than a simple expression.\n" +
             s"Plan:${plan.prettyJson}\n"))
        }
        // Cap the maximum length when logging an unresolved expression to avoid issues. This is a
        // CHECK constraint expression and should be relatively simple.
        val MAX_OUTPUT_LENGTH = 10 * 1024
        deltaAssert(
          resolvedExpr.resolved,
          name = "invariant.unresolvedExpression",
          msg = s"CHECK constraint child expression was not properly resolved",
          data = Map(
            "name" -> name,
            "checkExpr" -> expr.treeString.take(MAX_OUTPUT_LENGTH),
            "attributesExtracted" -> attributesExtracted.treeString.take(MAX_OUTPUT_LENGTH),
            "analyzedLogicalPlan" -> analyzedLogicalPlan.treeString.take(MAX_OUTPUT_LENGTH),
            "optimizedLogicalPlan" -> optimizedLogicalPlan.treeString.take(MAX_OUTPUT_LENGTH),
            "resolvedExpr" -> resolvedExpr.treeString.take(MAX_OUTPUT_LENGTH)
          )
        )
        resolvedExpr
    }

    CheckDeltaInvariant(executableExpr, columnExtractors.toSeq, constraint)
  }

override protected def doExecute(): RDD[InternalRow] = {
  if (constraints.isEmpty) return child.execute()

  // Resolve current_date()/current_time() expressions.
  // We resolve currentTime for all invariants together to make sure we use the same timestamp.
  val invariantsFakePlan = AnalysisHelper.FakeLogicalPlan(constraints, Nil)
  val newInvariantsPlan = optimizer.ComputeCurrentTime(invariantsFakePlan)
  val constraintsWithFixedTime = newInvariantsPlan.expressions.toArray

  child.execute().mapPartitionsInternal { rows =>
    val assertions = UnsafeProjection.create(constraintsWithFixedTime, child.output)
    rows.map { row =>
      assertions(row)
      row
    }
  }

case class CheckDeltaInvariant(
    child: Expression,
    columnExtractors: Seq[(String, Expression)],
    constraint: Constraint)
  extends Expression with NonSQLExpression with CodegenFallback {

  override def children: Seq[Expression] = child +: columnExtractors.map(_._2)
  override def dataType: DataType = NullType
  override def foldable: Boolean = false
  override def nullable: Boolean = true

  private def assertRule(input: InternalRow): Unit = constraint match {
    case n: NotNull =>
      if (child.eval(input) == null) {
        throw DeltaInvariantViolationException(n)
      }
    case c: Check =>
      val result = child.eval(input)
      if (result == null || result == false) {
        throw DeltaInvariantViolationException(
          c,
          columnExtractors.map {
            case (column, extractor) => column -> extractor.eval(input)
          }.toMap
        )
      }
  }

  override def eval(input: InternalRow): Any = {
    assertRule(input)
    null

