object IdentityColumnsTableFeature
  extends LegacyWriterFeature(name = "identityColumns", minWriterVersion = 6)
  with FeatureAutomaticallyEnabledByMetadata {
  override def metadataRequiresFeatureToBeEnabled(
      protocol: Protocol,
