      // Paths in the metadata column are canonicalized. Thus we must canonicalize the DV path.
      FileToDvDescriptor(
        SparkPath.fromPath(absolutePath(basePath, add.path)).urlEncoded,
        serializedDV)
    }
    val filePathToDVDf = sparkSession.createDataset(filePathToDV)

    val joinExpr = filePathToDVDf("path") === matchedRowsDf(FILE_NAME_COL)
    // Perform leftOuter join to make sure we do not eliminate any rows because of path
    // encoding issues. If there is such an issue we will detect it during the aggregation
    // of the bitmaps.
    val joinedDf = matchedRowsDf.join(filePathToDVDf, joinExpr, "leftOuter")
      .drop(FILE_NAME_COL)
      .withColumnRenamed("path", FILE_NAME_COL)
    joinedDf
  } else {
    // When the table has no DVs, just add a column to indicate that the existing dv is null
    matchedRowsDf.withColumn(FILE_DV_ID_COL, lit(null))
  }

  DeletionVectorBitmapGenerator.buildDeletionVectors(sparkSession, df, txn.deltaLog, txn)
}

def computeResult(): Seq[DeletionVectorResult] = {
  val aggregated = target
    .groupBy(col(FILE_NAME_COL), col(FILE_DV_ID_COL))
    .agg(aggColumns.head, aggColumns.tail: _*)
    .select(outputColumns: _*)

  import DeletionVectorResult.encoder
  val rowIndexData = aggregated.as[DeletionVectorData]
  val storedResults = rowIndexData.mapPartitions(bitmapStorageMapper())
  storedResults.as[DeletionVectorResult].collect()
}

protected def aggColumns: Seq[Column] = {
  Seq(createBitmapSetAggregator(col(ROW_INDEX_COL)).as(CardinalityAndBitmapStruct.name))
}

/** Create a bitmap set aggregator over the given column */
private def createBitmapSetAggregator(indexColumn: Column): Column = {
  val func = new BitmapAggregator(indexColumn.expr, RoaringBitmapArrayFormat.Portable)
  Column(func.toAggregateExpression(isDistinct = false))

override def createAggregationBuffer(): RoaringBitmapArray = new RoaringBitmapArray()

override def update(buffer: RoaringBitmapArray, input: InternalRow): RoaringBitmapArray = {
  val value = child.eval(input)
  // Ignore empty rows
  if (value != null) {
    buffer.add(value.asInstanceOf[Long])
  }
  buffer

override def buildReaderWithPartitionValues(
    sparkSession: SparkSession,
    dataSchema: StructType,
    partitionSchema: StructType,
    requiredSchema: StructType,
    filters: Seq[Filter],
    options: Map[String, String],
    hadoopConf: Configuration): PartitionedFile => Iterator[InternalRow] = {

  val useMetadataRowIndexConf = DeltaSQLConf.DELETION_VECTORS_USE_METADATA_ROW_INDEX
  val useMetadataRowIndex = sparkSession.sessionState.conf.getConf(useMetadataRowIndexConf)

  val parquetDataReader: PartitionedFile => Iterator[InternalRow] =
    super.buildReaderWithPartitionValues(
      sparkSession,
      prepareSchemaForRead(dataSchema),
      prepareSchemaForRead(partitionSchema),
      prepareSchemaForRead(requiredSchema),
      prepareFiltersForRead(filters),
      options,
      hadoopConf)

  val schemaWithIndices = requiredSchema.fields.zipWithIndex
  def findColumn(name: String): Option[ColumnMetadata] = {
    val results = schemaWithIndices.filter(_._1.name == name)
    if (results.length > 1) {
      throw new IllegalArgumentException(
        s"There are more than one column with name=`$name` requested in the reader output")
    }
    results.headOption.map(e => ColumnMetadata(e._2, e._1))
  }

  val isRowDeletedColumn = findColumn(IS_ROW_DELETED_COLUMN_NAME)
  val rowIndexColumnName = if (useMetadataRowIndex) {
    ParquetFileFormat.ROW_INDEX_TEMPORARY_COLUMN_NAME
  } else {
    ROW_INDEX_COLUMN_NAME
  }
  val rowIndexColumn = findColumn(rowIndexColumnName)

  // We don't have any additional columns to generate, just return the original reader as is.
  if (isRowDeletedColumn.isEmpty && rowIndexColumn.isEmpty) return parquetDataReader

  // We are using the row_index col generated by the parquet reader and there are no more
  // columns to generate.
  if (useMetadataRowIndex && isRowDeletedColumn.isEmpty) return parquetDataReader

  // Verify that either predicate pushdown with metadata column is enabled or optimizations
  // are disabled.
  require(useMetadataRowIndex || !optimizationsEnabled,
    "Cannot generate row index related metadata with file splitting or predicate pushdown")

  if (hasTablePath && isRowDeletedColumn.isEmpty) {
      throw new IllegalArgumentException(
        s"Expected a column $IS_ROW_DELETED_COLUMN_NAME in the schema")
  }

  val serializableHadoopConf = new SerializableConfiguration(hadoopConf)

  val useOffHeapBuffers = sparkSession.sessionState.conf.offHeapColumnVectorEnabled
  (partitionedFile: PartitionedFile) => {
    val rowIteratorFromParquet = parquetDataReader(partitionedFile)
    try {
      val iterToReturn =
        iteratorWithAdditionalMetadataColumns(
          partitionedFile,
          rowIteratorFromParquet,
          isRowDeletedColumn,
          rowIndexColumn,
          useOffHeapBuffers,

    int partitionIdx = sparkSchema.fields().length;
    for (int i = 0; i < partitionColumns.fields().length; i++) {
      ColumnVectorUtils.populate(
        (ConstantColumnVector) vectors[i + partitionIdx], partitionValues, i);
    }
  }

  rowIndexGenerator = ParquetRowIndexUtil.createGeneratorIfNeeded(sparkSchema);
}

private void initBatch() {
  initBatch(MEMORY_MODE, null, null);
}

public void initBatch(StructType partitionColumns, InternalRow partitionValues) {
  initBatch(MEMORY_MODE, partitionColumns, partitionValues);
}

/**
 * Returns the ColumnarBatch object that will be used for all rows returned by this reader.
 * This object is reused. Calling this enables the vectorized reader. This should be called
 * before any calls to nextKeyValue/nextBatch.
 */
public ColumnarBatch resultBatch() {
  if (columnarBatch == null) initBatch();
  return columnarBatch;
}

/**
 * Can be called before any rows are returned to enable returning columnar batches directly.
 */
public void enableReturningBatches() {
  returnColumnarBatch = true;
}

/**
 * Advances to the next batch of rows. Returns false if there are no more.
 */
public boolean nextBatch() throws IOException {
  for (ParquetColumnVector vector : columnVectors) {
    vector.reset();
  }
  columnarBatch.setNumRows(0);
  if (rowsReturned >= totalRowCount) return false;
  checkEndOfRowGroup();

  int num = (int) Math.min(capacity, totalCountLoadedSoFar - rowsReturned);
  for (ParquetColumnVector cv : columnVectors) {
    for (ParquetColumnVector leafCv : cv.getLeaves()) {
      VectorizedColumnReader columnReader = leafCv.getColumnReader();
      if (columnReader != null) {
        columnReader.readBatch(num, leafCv.getValueVector(),
          leafCv.getRepetitionLevelVector(), leafCv.getDefinitionLevelVector());
      }
    }
    cv.assemble();
  }
  // If needed, compute row indexes within a file.
  if (rowIndexGenerator != null) {
    rowIndexGenerator.populateRowIndex(columnVectors, num);
  }

def initFromPageReadStore(pages: PageReadStore): Unit = {
  if (!pages.getRowIndexOffset.isPresent) {
    throw new IOException("PageReadStore returned no row index offset.")
  }
  val startingRowIdx: Long = pages.getRowIndexOffset.get()
  if (pages.getRowIndexes.isPresent) {
    // The presence of `getRowIndexes` indicates that page skipping is effective and only
    // a subset of rows in the row group is going to be read. Note that there is a name
    // collision here: these row indexes (unlike ones this class is generating) are counted
    // starting from 0 in each of the row groups.
    rowIndexIterator = pages.getRowIndexes.get.asScala.map(idx => idx + startingRowIdx)
  } else {
    val numRowsInRowGroup = pages.getRowCount
    rowIndexIterator = (startingRowIdx until startingRowIdx + numRowsInRowGroup).iterator
  }
}

def populateRowIndex(columnVectors: Array[ParquetColumnVector], numRows: Int): Unit = {
  populateRowIndex(columnVectors(rowIndexColumnIdx).getValueVector, numRows)
}

def populateRowIndex(columnVector: WritableColumnVector, numRows: Int): Unit = {
  for (i <- 0 until numRows) {
    columnVector.putLong(i, rowIndexIterator.next())
  }

// When predicate pushdown is enabled we use _metadata.row_index. Therefore,
// we only need to construct the isRowDeleted column.
var index = 0
isRowDeletedColumnOpt.foreach { columnMetadata =>
  val isRowDeletedVector = writableVectors(index)
  if (useMetadataRowIndex) {
    rowIndexFilterOpt.get.materializeIntoVectorWithRowIndex(
      size, batch.column(rowIndexColumnOpt.get.index), isRowDeletedVector)
  } else {
    rowIndexFilterOpt.get
      .materializeIntoVector(rowIndex, rowIndex + size, isRowDeletedVector)

// Iceberg spec requires partition columns in data files
val writePartitionColumns = IcebergCompat.isAnyEnabled(metadata)
// Retain only a minimal selection of Spark writer options to avoid any potential
// compatibility issues
val options = (writeOptions match {
  case None => Map.empty[String, String]
  case Some(writeOptions) =>
    writeOptions.options.filterKeys { key =>
      key.equalsIgnoreCase(DeltaOptions.MAX_RECORDS_PER_FILE) ||
        key.equalsIgnoreCase(DeltaOptions.COMPRESSION)
    }.toMap
}) + (DeltaOptions.WRITE_PARTITION_COLUMNS -> writePartitionColumns.toString)

try {
  DeltaFileFormatWriter.write(
    sparkSession = spark,
    plan = physicalPlan,
    fileFormat = deltaLog.fileFormat(protocol, metadata), // TODO support changing formats.
    committer = committer,
    outputSpec = outputSpec,
    // scalastyle:off deltahadoopconfiguration
    hadoopConf =
      spark.sessionState.newHadoopConfWithOptions(metadata.configuration ++ deltaLog.options),
    // scalastyle:on deltahadoopconfiguration
    partitionColumns = partitioningColumns,

// We should first sort by dynamic partition columns, then bucket id, and finally sorting
// columns.
val requiredOrdering = partitionColumns.drop(numStaticPartitionCols) ++
  writerBucketSpec.map(_.bucketIdExpression) ++ sortColumns
val writeFilesOpt = V1WritesUtils.getWriteFilesOpt(plan)

// SPARK-40588: when planned writing is disabled and AQE is enabled,
// plan contains an AdaptiveSparkPlanExec, which does not know
// its final plan's ordering, so we have to materialize that plan first
// it is fine to use plan further down as the final plan is cached in that plan
def materializeAdaptiveSparkPlan(plan: SparkPlan): SparkPlan = plan match {
  case a: AdaptiveSparkPlanExec => a.finalPhysicalPlan
  case p: SparkPlan => p.withNewChildren(p.children.map(materializeAdaptiveSparkPlan))
}

// the sort order doesn't matter
val actualOrdering = writeFilesOpt
  .map(_.child)
  .getOrElse(materializeAdaptiveSparkPlan(plan))
  .outputOrdering
val orderingMatched = V1WritesUtils.isOrderingMatched(requiredOrdering, actualOrdering)

SQLExecution.checkSQLExecutionId(sparkSession)

// propagate the description UUID into the jobs, so that committers
// get an ID guaranteed to be unique.
job.getConfiguration.set("spark.sql.sources.writeJobUUID", description.uuid)

// When `PLANNED_WRITE_ENABLED` is true, the optimizer rule V1Writes will add logical sort
// operator based on the required ordering of the V1 write command. So the output
// ordering of the physical plan should always match the required ordering. Here
// we set the variable to verify this behavior in tests.
// There are two cases where FileFormatWriter still needs to add physical sort:
// 1) When the planned write config is disabled.
// 2) When the concurrent writers are enabled (in this case the required ordering of a
//    V1 write command will be empty).
if (DeltaUtils.isTesting) outputOrderingMatched = orderingMatched

if (writeFilesOpt.isDefined) {
  // build `WriteFilesSpec` for `WriteFiles`
  val concurrentOutputWriterSpecFunc = (plan: SparkPlan) => {
    val sortPlan = createSortPlan(plan, requiredOrdering, outputSpec)
    createConcurrentOutputWriterSpec(sparkSession, sortPlan, sortColumns)
  }
  val writeSpec = WriteFilesSpec(
    description = description,
    committer = committer,
    concurrentOutputWriterSpecFunc = concurrentOutputWriterSpecFunc
  )
  executeWrite(sparkSession, plan, writeSpec, job)
} else {
  executeWrite(
    sparkSession,
    plan,
    job,
    description,
    committer,
    outputSpec,
    requiredOrdering,
    partitionColumns,
    sortColumns,
    orderingMatched
  )

